import React, { useState, useEffect } from 'react';
import { Button, Form, Container, Row, Col, Card } from 'react-bootstrap';
import { useNavigate, useLocation } from 'react-router-dom';
import axios from 'axios';

const AuthForm = ({ setUser }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('user');
  const [isLogin, setIsLogin] = useState(true);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const navigate = useNavigate();
  const location = useLocation();
  const from = location.state?.from?.pathname || '/';

  useEffect(() => {
    setEmail('');
    setPassword('');
    setError('');
  }, []);

  const handleSubmit = async (e) => {
  e.preventDefault();
  setLoading(true);
  setError('');

  try {
    if (isLogin) {
      // Login API request
      const response = await axios.post('http://localhost:8000/api/auth/login', {
        email,
        password,
      });

      if (response.data.accessToken && response.data.refreshToken) {
        // Store the tokens and user data
        localStorage.setItem('accessToken', response.data.accessToken);
        localStorage.setItem('refreshToken', response.data.refreshToken);
        localStorage.setItem('user', JSON.stringify(response.data.user));

        // Redirect based on role
        if (response.data.user.role === 'admin') {
          navigate('/admin-dashboard');
        } else {
          navigate(from, { replace: true });
        }
      } else {
        setError("Login failed: Token missing in response.");
      }
    } else {
      // Signup API request
      const response = await axios.post('http://localhost:8000/api/auth/register', {
        email,
        password,
        role,
      });

      alert(response.data.message || "Signup successful. Please log in.");
      setIsLogin(true); // Switch to login mode after signup
    }
  } catch (error) {
    console.error("❌ Auth Error:", error.response?.data || error.message);
    setError(error.response?.data?.message || "Something went wrong.");
  } finally {
    setLoading(false);
  }
};

  

  const toggleMode = () => {
    setIsLogin(!isLogin);
    setEmail('');
    setPassword('');
    setError('');
  };

  return (
    <Container className="mt-4 auth-form-container">
      <Row className="justify-content-center">
        <Col md={6}>
          <Card className="shadow-sm">
            <Card.Body>
              <h2 className="text-center">{isLogin ? 'Login' : 'Signup'}</h2>
              {error && <p className="text-danger text-center">{error}</p>}
              <Form onSubmit={handleSubmit} autoComplete="off"> {/* Prevent autofill globally */}
                <Form.Group controlId="formBasicEmail" className="form-group">
                  <Form.Label>Email address</Form.Label>
                  <Form.Control
                    type="email"
                    placeholder="Enter email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                    name="email"
                    autoComplete="new-email"  // Disable autofill on email field
                  />
                </Form.Group>

                <Form.Group controlId="formBasicPassword" className="form-group">
                  <Form.Label>Password</Form.Label>
                  <Form.Control
                    type="password"
                    placeholder="Password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                    name="password"
                    autoComplete="new-password"  // Disable autofill on password field
                  />
                </Form.Group>

                {!isLogin && (
                  <Form.Group controlId="formBasicRole" className="form-group">
                    <Form.Label>Role</Form.Label>
                    <Form.Control
                      as="select"
                      value={role}
                      onChange={(e) => setRole(e.target.value)}
                      required
                    >
                      <option value="user">User</option>
                      <option value="admin">Admin</option>
                    </Form.Control>
                  </Form.Group>
                )}

                <Button
                  variant="primary"
                  type="submit"
                  className="mt-3 w-100"
                  disabled={loading}
                >
                  {loading ? 'Processing...' : isLogin ? 'Login' : 'Signup'}
                </Button>
              </Form>

              <Button
                variant="link"
                onClick={toggleMode}
                className="mt-3 w-100 text-center"
              >
                {isLogin ? 'Switch to Signup' : 'Switch to Login'}
              </Button>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default AuthForm;
